do $$ begin if to_regclass('public.theo_live_workers') is null or (select count(*) from auth.users) <> 1 then raise exception 'Stopped: this is not the D.Scribe Theo Live staging project with exactly one signed-in test user. Nothing was changed.'; end if; end $$;
select u.id as test_user_id, b.tier, b.ink_balance, (select value from public.ink_meter_settings where key = 'ink_per_vendor_dollar') as ink_per_vendor_dollar, (select count(*) from public.ink_rates) as ink_rate_rows from auth.users u join public.ink_balances b on b.user_id = u.id;
