insert into public.ink_meter_settings (key, value, note) select 'ink_per_vendor_dollar', 102, 'Staging seed, same value as migration 027.' where to_regclass('public.theo_live_workers') is not null and (select count(*) from auth.users) = 1 on conflict (key) do nothing;
