insert into public.ink_balances (user_id, ink_balance, tier, ink_period_start) select u.id, 1000, 'pro', now() from auth.users u where to_regclass('public.theo_live_workers') is not null and (select count(*) from auth.users) = 1 on conflict (user_id) do update set ink_balance = excluded.ink_balance, tier = excluded.tier, ink_period_start = excluded.ink_period_start, updated_at = now();
